$ErrorActionPreference='Stop'
$root='C:\Users\JAMAL\Desktop\Flafy'
$log=Join-Path $root 'flafy-build.log'
New-Item -ItemType Directory -Force -Path $root | Out-Null
Start-Transcript -Path $log -Force | Out-Null
try {
  Write-Output 'FLAFY_BUILD_START'
  $dist=Join-Path $root 'dist'; $srcTauri=Join-Path $root 'src-tauri'
  New-Item -ItemType Directory -Force -Path $dist,(Join-Path $srcTauri 'src') | Out-Null
  '{"name":"flafy","private":true,"version":"1.0.0","scripts":{"tauri":"tauri"},"devDependencies":{"@tauri-apps/cli":"^2.9.4"}}' | Set-Content (Join-Path $root 'package.json') -Encoding UTF8
  @'
[package]
name="flafy"
version="1.0.0"
description="Flafy Personal Control Room"
authors=["Jamal & Sol"]
edition="2021"
[lib]
name="flafy_lib"
crate-type=["staticlib","cdylib","rlib"]
[build-dependencies]
tauri-build={version="2",features=[]}
[dependencies]
tauri={version="2",features=[]}
serde={version="1",features=["derive"]}
serde_json="1"
sysinfo="0.40"
[profile.release]
codegen-units=1
lto=true
opt-level="s"
panic="abort"
strip=true
'@ | Set-Content (Join-Path $srcTauri 'Cargo.toml') -Encoding UTF8
  'fn main(){tauri_build::build()}' | Set-Content (Join-Path $srcTauri 'build.rs') -Encoding UTF8
  @'
{"$schema":"https://schema.tauri.app/config/2","productName":"Flafy","version":"1.0.0","identifier":"com.jamal.flafy","build":{"frontendDist":"../dist"},"app":{"withGlobalTauri":true,"windows":[{"label":"main","title":"Flafy","fullscreen":true,"decorations":false,"resizable":true,"visible":true,"focus":true}],"security":{"csp":null}},"bundle":{"active":false}}
