use serde::Serialize;use std::{env,fs,path::PathBuf,process::Command,thread,time::Duration};use sysinfo::{Disks,System};
#[derive(Serialize)] struct Stats{cpu:f32,ram:f32,storage:f32,total_ram_gb:f64,used_ram_gb:f64}
#[tauri::command] fn system_stats()->Stats{let mut s=System::new_all();thread::sleep(Duration::from_millis(220));s.refresh_cpu_usage();s.refresh_memory();let total=s.total_memory() as f64;let used=s.used_memory() as f64;let ram=if total>0.0{(used/total*100.0)as f32}else{0.0};let disks=Disks::new_with_refreshed_list();let(mut dt,mut da)=(0u64,0u64);for d in disks.list(){dt+=d.total_space();da+=d.available_space();}let storage=if dt>0{((dt-da)as f64/dt as f64*100.0)as f32}else{0.0};Stats{cpu:s.global_cpu_usage(),ram,storage,total_ram_gb:total/1073741824.0,used_ram_gb:used/1073741824.0}}
fn home()->PathBuf{PathBuf::from(env::var("USERPROFILE").unwrap_or_else(|_|"C:\\Users\\JAMAL".into()))}
#[tauri::command] fn open_location(kind:String)->Result<(),String>{let h=home();let t=match kind.as_str(){"flafy"=>h.join("Desktop\\Flafy"),"downloads"=>h.join("Downloads"),"desktop"=>h.join("Desktop"),"mofakrati"=>h.join("Desktop\\مفكرتي"),_=>return Err("unknown target".into())};Command::new("explorer").arg(t).spawn().map_err(|e|e.to_string())?;Ok(())}
#[tauri::command] fn project_status()->serde_json::Value{let h=home();serde_json::json!({"flafy":h.join("Desktop\\Flafy").exists(),"mofakrati":h.join("Desktop\\مفكرتي").exists(),"downloads":h.join("Downloads").exists()})}
#[cfg_attr(mobile,tauri::mobile_entry_point)] pub fn run(){tauri::Builder::default().setup(|_|{let _=fs::write(env::temp_dir().join("Flafy_runtime_ok.txt"),"runtime-ok");Ok(())}).invoke_handler(tauri::generate_handler![system_stats,open_location,project_status]).run(tauri::generate_context!()).expect("Flafy failed");}
'@ | Set-Content (Join-Path $srcTauri 'src\lib.rs') -Encoding UTF8
