<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flafy</title><link rel="stylesheet" href="styles.css"></head><body><div class="shell"><header class="top"><div class="brand"><div class="mark">F</div><div><h1>Flafy</h1><p>Personal Control Room · Jamal & Sol</p></div></div><div class="topright"><span class="pill ok">SYSTEM LIVE</span><span id="nowTop" class="pill">--:--</span></div></header><main class="layout"><section class="hero panel"><div><span class="eyebrow">FLAFY // HOME</span><h2 id="greet">صباح الخير، جمال</h2><p class="lead">واجهة واحدة لكل شغلك، بدون زحمة وبدون بيانات وهمية.</p></div><div class="focus"><span>FOCUS</span><b>شغلة رئيسية واحدة، والباقي تحت عين Flafy.</b><small>الواجهة تراقب الجهاز والمشاريع وتخليك تنتقل بسرعة بين الأشياء المهمة.</small></div><div class="heroFoot"><div><div id="clock" class="clock">--:--</div><div id="date" class="date">---</div></div><div class="weather"><span id="weatherIcon">◌</span><div><b id="weatherTemp">--°</b><small id="weatherText">Hameln · loading</small></div></div></div></section><section class="projects panel"><div class="head"><b>Projects</b><span>Workspace</span></div><div class="rows"><button data-open="flafy"><span>Flafy</span><em class="good">ACTIVE</em></button><button data-open="mofakrati"><span>مفكرتي</span><em id="mofakratiState">CHECKING</em></button><button><span>MedFlux</span><em>MONITORED</em></button><button><span>Net Download Manager</span><em class="good">READY</em></button><button><span>Project Zomboid</span><em>AVAILABLE</em></button></div></section><section class="system panel"><div class="head"><b>System</b><span>Real telemetry</span></div><div class="stats"><div class="stat"><label>CPU <span id="cpuVal">--%</span></label><div><i id="cpuBar"></i></div></div><div class="stat"><label>Memory <span id="ramVal">--%</span></label><div><i id="ramBar"></i></div></div><div class="stat"><label>Storage <span id="diskVal">--%</span></label><div><i id="diskBar"></i></div></div></div><div class="mini" id="ramText">Reading device…</div></section><section class="actions panel"><div class="head"><b>Quick Actions</b><span>Launch</span></div><div class="actionGrid"><button data-open="downloads">Downloads</button><button data-open="desktop">Desktop</button><button data-open="flafy">Flafy Folder</button><button id="refreshBtn">Refresh All</button></div></section><section class="signals panel"><div class="head"><b>Signals</b><span>Live state</span></div><div class="signalGrid"><div><span>Weather</span><b id="sigWeather">Connecting</b></div><div><span>System</span><b id="sigSystem">Reading</b></div><div><span>Projects</span><b id="sigProjects">Checking</b></div><div><span>Mode</span><b>Borderless Fullscreen</b></div></div></section><section class="sol panel"><div class="head"><b>Sol Feed</b><span>Signal, not noise</span></div><div class="solGrid"><article><span>NOW</span><b id="solNow">Flafy عم تجمع الصورة الكاملة.</b><small>بيانات الجهاز والطقس والمشاريع تتحدث لحالها.</small></article><article><span>SYSTEM</span><b>خفيفة ومبنية على Tauri + Rust.</b><small>ما في Chromium كامل شغال بالخلفية.</small></article><article><span>RULE</span><b>الإغلاق فقط بعد PASS فعلي.</b><small>Build وRuntime لازم ينجحوا أولًا.</small></article></div></section></main><footer><span>Flafy 1.0</span><span id="footerState">Initializing…</span></footer></div><script src="app.js"></script></body></html>
'@ | Set-Content (Join-Path $dist 'index.html') -Encoding UTF8
  @'
:root{--bg:#090c11;--panel:#121722;--line:#273044;--text:#f5f7fb;--muted:#8d98ad;--blue:#6ea8ff;--violet:#9b8cff;--green:#67d7a5}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;font-family:Segoe UI,Tahoma,Arial,sans-serif;background:radial-gradient(circle at 12% 4%,#132035 0,transparent 28%),radial-gradient(circle at 88% 0,#1a1530 0,transparent 25%),var(--bg);color:var(--text)}body{min-width:1000px}.shell{height:100vh;padding:18px 22px;display:grid;grid-template-rows:auto 1fr auto;gap:14px}.top{display:flex;justify-content:space-between;align-items:center}.brand{display:flex;align-items:center;gap:12px}.mark{width:46px;height:46px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(145deg,#d7e6ff,#95baff,#b6a8ff);color:#10131a;font-weight:900}.brand h1{margin:0;font-size:22px}.brand p{margin:3px 0 0;color:var(--muted);font-size:10px}.topright{display:flex;gap:8px}.pill{border:1px solid var(--line);padding:8px 10px;border-radius:10px;color:var(--muted);font-size:10px;background:#ffffff04}.pill.ok{color:var(--green)}.layout{min-height:0;display:grid;grid-template-columns:1fr 1.35fr 1fr;grid-template-rows:1.15fr .8fr .9fr;gap:12px}.panel{background:linear-gradient(180deg,#141923ee,#10151fee);border:1px solid var(--line);border-radius:18px;box-shadow:0 18px 50px #0005;overflow:hidden}.hero{grid-column:2;grid-row:1/3;padding:28px;display:flex;flex-direction:column;justify-content:space-between}.eyebrow{color:var(--blue);font-size:10px}.hero h2{font-size:36px;margin:8px 0}.lead{color:var(--muted);font-size:13px}.focus{padding:18px;border:1px solid #2b3950;border-radius:15px;background:#0e141d}.focus span{font-size:9px;color:var(--blue)}.focus b{display:block;font-size:18px;margin:8px 0}.focus small{color:var(--muted);line-height:1.7}.heroFoot{display:flex;justify-content:space-between;align-items:end}.clock{font-size:58px;font-weight:700}.date{color:var(--muted);font-size:11px;margin-top:5px}.weather{display:flex;gap:12px;align-items:center;direction:ltr}.weather>span{font-size:28px}.weather b{font-size:24px}.weather small{display:block;color:var(--muted)}.head{padding:13px 15px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.head b{font-size:12px}.head span{font-size:9px;color:var(--muted)}.projects{grid-column:3;grid-row:1}.rows{padding:10px;display:grid;gap:7px}.rows button,.actionGrid button{border:1px solid #273044;background:#ffffff04;color:var(--text);border-radius:10px;padding:10px 11px;display:flex;justify-content:space-between;cursor:pointer}.rows em{font-style:normal;color:var(--muted);font-size:9px}.rows em.good{color:var(--green)}.system{grid-column:1;grid-row:1}.stats{padding:15px}.stat{margin-bottom:14px}.stat label{display:flex;justify-content:space-between;color:var(--muted);font-size:10px;margin-bottom:6px}.stat>div{height:7px;background:#222a38;border-radius:20px;overflow:hidden}.stat i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--blue),var(--violet));transition:width .35s}.mini{padding:0 15px 14px;color:var(--muted);font-size:10px}.actions{grid-column:3;grid-row:2}.actionGrid{padding:10px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.actionGrid button{justify-content:center}.signals{grid-column:1;grid-row:2}.signalGrid{padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.signalGrid div{padding:11px;border:1px solid #273044;border-radius:10px;background:#ffffff03}.signalGrid span{display:block;color:var(--muted);font-size:9px}.signalGrid b{display:block;margin-top:5px;font-size:10px}.sol{grid-column:1/4;grid-row:3}.solGrid{height:calc(100% - 44px);padding:12px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.solGrid article{padding:15px;border:1px solid #273044;border-radius:12px;background:#ffffff03}.solGrid article span{color:var(--blue);font-size:9px}.solGrid article b{display:block;margin:7px 0;font-size:12px}.solGrid article small{color:var(--muted)}footer{display:flex;justify-content:space-between;color:var(--muted);font-size:9px}
'@ | Set-Content (Join-Path $dist 'styles.css') -Encoding UTF8
  @'
const I=()=>window.__TAURI__?.core?.invoke,E=id=>document.getElementById(id);function tick(){const d=new Date();E('clock').textContent=d.toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});E('nowTop').textContent=E('clock').textContent;E('date').textContent=d.toLocaleDateString('ar-DE',{weekday:'long',year:'numeric',month:'long',day:'numeric'});E('greet').textContent=(d.getHours()<12?'صباح الخير':'مساء الخير')+'، جمال'}async function stats(){try{const s=await I()('system_stats');[['cpu',s.cpu],['ram',s.ram],['disk',s.storage]].forEach(([k,v])=>{E(k+'Val').textContent=Math.round(v)+'%';E(k+'Bar').style.width=Math.min(100,v)+'%'});E('ramText').textContent=`RAM ${s.used_ram_gb.toFixed(1)} / ${s.total_ram_gb.toFixed(1)} GB`;E('sigSystem').textContent='LIVE';E('footerState').textContent='Telemetry online'}catch{E('sigSystem').textContent='ERROR'}}async function projects(){try{const p=await I()('project_status');E('mofakratiState').textContent=p.mofakrati?'FOUND':'NOT FOUND';E('mofakratiState').className=p.mofakrati?'good':'';E('sigProjects').textContent='READY'}catch{E('sigProjects').textContent='ERROR'}}async function weather(){try{const r=await fetch('https://api.open-meteo.com/v1/forecast?latitude=52.1039&longitude=9.3562&current=temperature_2m,weather_code&timezone=Europe%2FBerlin');const j=await r.json(),t=Math.round(j.current.temperature_2m),c=j.current.weather_code;E('weatherTemp').textContent=t+'°';E('weatherText').textContent='Hameln · '+(c===0?'Clear':c<4?'Partly cloudy':c<60?'Cloudy':c<80?'Rain':'Snow');E('weatherIcon').textContent=c===0?'☀':c<4?'◐':c<60?'☁':c<80?'☂':'❄';E('sigWeather').textContent='LIVE'}catch{E('weatherText').textContent='Hameln · offline';E('sigWeather').textContent='OFFLINE'}}async function refresh(){await Promise.allSettled([stats(),projects(),weather()]);E('solNow').textContent='Flafy محدثة وهلأ كل الإشارات قدامك.'}document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>I()('open_location',{kind:b.dataset.open}));E('refreshBtn').onclick=refresh;tick();setInterval(tick,1000);refresh();setInterval(stats,4000);setInterval(weather,900000);
'@ | Set-Content (Join-Path $dist 'app.js') -Encoding UTF8
  Remove-Item (Join-Path $env:TEMP 'Flafy_runtime_ok.txt') -Force -ErrorAction SilentlyContinue
  if(-not (Get-Command cargo -ErrorAction SilentlyContinue)){throw 'Rust/Cargo is not installed'}
  Set-Location $root; npm install; if($LASTEXITCODE){throw 'npm install failed'}; npx tauri build --no-bundle; if($LASTEXITCODE){throw 'tauri build failed'}
  $exe=Join-Path $srcTauri 'target\release\flafy.exe'; if(-not(Test-Path $exe)){throw 'Flafy exe missing'}
  $proc=Start-Process $exe -PassThru; $marker=Join-Path $env:TEMP 'Flafy_runtime_ok.txt'; $ok=$false
  for($i=0;$i -lt 30;$i++){Start-Sleep -Milliseconds 500;if((Test-Path $marker)-and(-not $proc.HasExited)){$ok=$true;break}}
  if(-not $ok){throw 'runtime validation failed'}
  "BUILD_OK`nRUNTIME_OK`nEXE=$exe`nTIME=$(Get-Date -Format o)" | Set-Content (Join-Path $root 'FLAFY_COMPLETE.txt') -Encoding UTF8
  Write-Output 'FLAFY_COMPLETE_RUNTIME_PASS'; Stop-Transcript|Out-Null; exit 0
}catch{Write-Error $_;"FAILED`n$($_.Exception.Message)`nTIME=$(Get-Date -Format o)"|Set-Content(Join-Path $root 'FLAFY_FAILED.txt') -Encoding UTF8;Write-Output 'FLAFY_FAILED';try{Stop-Transcript|Out-Null}catch{};exit 1}
